ATTACH 'analytics' AS app (
  TYPE vgi,
  LOCATION 'https://worker.example.com/vgi/'
);
SHOW TABLES FROM app.main;
SELECT * FROM app.main.events
LIMIT 10;
DETACH app;

ATTACH 'example' AS local_worker (
  TYPE vgi, LOCATION './my_worker',
  pool true
);
SELECT * FROM vgi_worker_pool_stats();
DETACH local_worker;
